-- ISOLATED SYNTHETIC FIXTURE ONLY. No production migration or credential setup.
DO $$BEGIN IF (current_database()<>'design_executor_synthetic' OR current_setting('design_executor.synthetic_fixture',true) IS DISTINCT FROM 'offline-stage6-only' OR current_setting('server_version_num')::int/10000<>17 OR to_regnamespace('design_normalization_processing') IS NULL OR to_regnamespace('design_canonical_verification') IS NOT NULL) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CANONICAL_FIXTURE_REQUIRED';END IF;END$$;
CREATE ROLE design_canonical_authorizer LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
CREATE ROLE design_canonical_verifier LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
GRANT CONNECT ON DATABASE design_executor_synthetic TO design_canonical_authorizer,design_canonical_verifier;
CREATE SCHEMA design_canonical_verification AUTHORIZATION design_identity_owner;
REVOKE ALL ON SCHEMA design_canonical_verification FROM PUBLIC,anon,authenticated;
GRANT USAGE ON SCHEMA design_canonical_verification TO design_normalization_runtime,design_canonical_authorizer,design_canonical_verifier,design_managed_image_capability;
GRANT CREATE ON SCHEMA design_canonical_verification TO design_managed_image_capability;
CREATE TABLE design_canonical_verification.config(singleton boolean PRIMARY KEY CHECK(singleton),policy jsonb NOT NULL,verifier jsonb NOT NULL);
CREATE TABLE design_canonical_verification.tasks(id text PRIMARY KEY,authority jsonb NOT NULL,request_id text NOT NULL,task jsonb NOT NULL,expires_at timestamptz NOT NULL,active boolean NOT NULL DEFAULT true);
CREATE TABLE design_canonical_verification.reports(task_id text PRIMARY KEY REFERENCES design_canonical_verification.tasks,report jsonb NOT NULL,active boolean NOT NULL DEFAULT true);
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['config','tasks','reports'] LOOP EXECUTE format('ALTER TABLE design_canonical_verification.%I OWNER TO design_identity_owner',t);EXECUTE format('ALTER TABLE design_canonical_verification.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE design_canonical_verification.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY capability_only ON design_canonical_verification.%I TO design_managed_image_capability USING(true) WITH CHECK(true)',t);EXECUTE format('GRANT SELECT ON design_canonical_verification.%I TO design_managed_image_capability',t);EXECUTE format('CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON design_canonical_verification.%I FOR EACH ROW EXECUTE FUNCTION design_managed_image.immutable_row()',t);END LOOP;END$$;
GRANT INSERT,UPDATE(active) ON design_canonical_verification.tasks,design_canonical_verification.reports TO design_managed_image_capability;
-- config is seeded exactly once by the offline fixture owner from reviewed code constants.
-- No runtime/issuer may INSERT/UPDATE config, and its immutable trigger forbids changes.
CREATE FUNCTION design_canonical_verification.resolve(token text,scope jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE r jsonb;BEGIN
 IF (session_user NOT IN ('design_normalization_runtime','design_canonical_authorizer','design_canonical_verifier') OR token IS NULL OR length(token) NOT BETWEEN 32 AND 200 OR token~'[[:space:][:cntrl:]]') IS DISTINCT FROM false THEN RAISE EXCEPTION 'CANONICAL_DENIED' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('design-prepared:transaction:v1',0));r:=design_identity.resolve_hash(encode(sha256(convert_to(token,'UTF8')),'hex'),scope);IF ((r->>'expiresAt')::timestamptz<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CANONICAL_DENIED';END IF;RETURN r->'authority';END$$;
CREATE FUNCTION design_canonical_verification.make_task(a jsonb,tid text,rid text) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE w jsonb;n jsonb;receipt jsonb;c design_canonical_verification.config;src jsonb;tr jsonb;BEGIN
 w:=design_normalization_processing.check_bound(a,rid);n:=w->'artifact';SELECT * INTO STRICT c FROM design_canonical_verification.config WHERE singleton=true;
 SELECT o.receipt INTO STRICT receipt FROM design_managed_normalized.objects o WHERE o.artifact_digest=design_dependency_authority.digest(n);PERFORM design_managed_normalized.check_object(a,design_dependency_authority.digest(n),receipt);
 src:=n->'parentResponse'->'descriptor'->'source';tr:=n->'parentResponse'->'descriptor'->'requestedTransform';
 IF (c.policy->>'id' IS DISTINCT FROM 'synthetic-pinned-producer-rgb8-v1' OR c.policy->>'scope' IS DISTINCT FROM 'synthetic_fixture_only' OR src->'width' IS DISTINCT FROM c.policy->'fixture'->'width' OR src->'height' IS DISTINCT FROM c.policy->'fixture'->'height' OR tr->'width' IS DISTINCT FROM src->'width' OR tr->'height' IS DISTINCT FROM src->'height' OR NOT (c.policy->'parentTransform'->'maxEdges' @> jsonb_build_array(tr->'maxEdge')) OR n->'output'->'width' IS DISTINCT FROM src->'width' OR n->'output'->'height' IS DISTINCT FROM src->'height') IS DISTINCT FROM false THEN RAISE EXCEPTION 'CANONICAL_UNSUPPORTED' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('schemaVersion','design-normalized-strict-task-v1','taskId',tid,'claimedArtifact',w,'objectReceipt',receipt,'fixtureId',c.policy->'fixture'->'id','verifier',c.verifier,'policy',c.policy);END$$;
CREATE FUNCTION design_canonical_verification.context(a jsonb,tid text) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE t design_canonical_verification.tasks;c jsonb;BEGIN
 SELECT * INTO STRICT t FROM design_canonical_verification.tasks x WHERE x.id=tid FOR SHARE;IF (NOT t.active OR t.authority IS DISTINCT FROM a OR t.expires_at<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CANONICAL_DENIED' USING ERRCODE='42501';END IF;
 c:=design_canonical_verification.make_task(a,tid,t.request_id);IF (c IS DISTINCT FROM t.task OR t.expires_at<=clock_timestamp()) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CANONICAL_CHANGED' USING ERRCODE='42501';END IF;RETURN c;END$$;
CREATE FUNCTION design_canonical_verification.binding(t jsonb) RETURNS jsonb LANGUAGE sql SET search_path=pg_catalog AS $$SELECT design_managed_normalized.binding(jsonb_build_object('taskId',t->'taskId','artifact',t->'claimedArtifact'->'artifact','objectReceipt',t->'objectReceipt','verifier',t->'verifier','policyVersion',t->'policy'->'id')) || jsonb_build_object('schemaVersion','design-normalized-strict-binding-v1','taskDigest',design_dependency_authority.digest(t),'claimedArtifactDigest',design_dependency_authority.digest(t->'claimedArtifact'),'processingProvenance',t->'claimedArtifact'->'processingProvenance','processingProvenanceDigest',design_dependency_authority.digest(t->'claimedArtifact'->'processingProvenance'),'policy',t->'policy','policyDigest',design_dependency_authority.digest(t->'policy'),'fixture',t->'policy'->'fixture')$$;
CREATE FUNCTION design_canonical_verification.issue_task(token text,scope jsonb,tid text,rid text,ttl bigint) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;t jsonb;BEGIN
 IF (session_user IS DISTINCT FROM 'design_canonical_authorizer' OR tid IS NULL OR tid!~'^[A-Za-z0-9_-]{1,100}$' OR rid IS NULL OR rid!~'^[A-Za-z0-9_-]{1,100}$' OR ttl IS NULL OR ttl NOT BETWEEN 1 AND 900000) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CANONICAL_DENIED' USING ERRCODE='42501';END IF;
 a:=design_canonical_verification.resolve(token,scope);t:=design_canonical_verification.make_task(a,tid,rid);INSERT INTO design_canonical_verification.tasks VALUES(tid,a,rid,t,clock_timestamp()+ttl*interval '1 millisecond',true);RETURN design_canonical_verification.context(design_canonical_verification.resolve(token,scope),tid);END$$;
CREATE FUNCTION design_canonical_verification.read_task(token text,scope jsonb,tid text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;t jsonb;BEGIN
 IF session_user IS DISTINCT FROM 'design_canonical_verifier' THEN RAISE EXCEPTION 'CANONICAL_DENIED' USING ERRCODE='42501';END IF;a:=design_canonical_verification.resolve(token,scope);t:=design_canonical_verification.context(a,tid);IF (t IS DISTINCT FROM design_canonical_verification.context(design_canonical_verification.resolve(token,scope),tid)) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CANONICAL_CHANGED';END IF;RETURN t;END$$;
CREATE FUNCTION design_canonical_verification.guard_task(token text,scope jsonb,tid text,td text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE t jsonb;BEGIN
 IF session_user IS DISTINCT FROM 'design_canonical_verifier' THEN RAISE EXCEPTION 'CANONICAL_DENIED' USING ERRCODE='42501';END IF;t:=design_canonical_verification.read_task(token,scope,tid);IF (td IS DISTINCT FROM design_dependency_authority.digest(t)) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CANONICAL_CHANGED' USING ERRCODE='42501';END IF;RETURN true;END$$;
CREATE FUNCTION design_canonical_verification.check_report(t jsonb,r jsonb) RETURNS boolean LANGUAGE plpgsql SET search_path=pg_catalog AS $$DECLARE b jsonb;c jsonb;e jsonb;state text;BEGIN
 b:=design_canonical_verification.binding(t);c:=r->'checks';IF (NOT design_managed_image.exact(r,ARRAY['schemaVersion','taskDigest','verificationBinding','checks','state','evidence','submissionAuthorized','adoptionAuthorized','publicEligible']) OR r->>'schemaVersion' IS DISTINCT FROM 'design-normalized-strict-report-v1' OR r->>'taskDigest' IS DISTINCT FROM design_dependency_authority.digest(t) OR r->'verificationBinding' IS DISTINCT FROM b OR r->'submissionAuthorized' IS DISTINCT FROM 'false'::jsonb OR r->'adoptionAuthorized' IS DISTINCT FROM 'false'::jsonb OR r->'publicEligible' IS DISTINCT FROM 'false'::jsonb OR NOT design_managed_image.exact(c,ARRAY['fixturePngComplete','sourceExactFixtureProducerMatch','parentExactProducerMatch','normalizedPngComplete','normalizedPixelsEqual','metadataAbsent','identityOrientation','sameGeometry']) OR EXISTS(SELECT 1 FROM jsonb_each(c) x WHERE x.value NOT IN ('"verified"'::jsonb,'"unknown"'::jsonb,'"failed"'::jsonb))) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CANONICAL_REPORT_INVALID' USING ERRCODE='42501';END IF;
 state:=CASE WHEN EXISTS(SELECT 1 FROM jsonb_each_text(c) x WHERE x.value='failed') THEN 'validation_failed' WHEN EXISTS(SELECT 1 FROM jsonb_each_text(c) x WHERE x.value='unknown') THEN 'pending_validation' ELSE 'evidence_complete' END;
 e:=CASE WHEN state='evidence_complete' THEN jsonb_build_object('schemaVersion','design-normalized-strict-evidence-v1','id','strict-verification-'||design_dependency_authority.digest(jsonb_build_object('binding',b,'checks',c)),'taskDigest',design_dependency_authority.digest(t),'verificationBindingDigest',design_dependency_authority.digest(b),'policyDigest',design_dependency_authority.digest(t->'policy'),'verifier',t->'verifier','checks',c) ELSE 'null'::jsonb END;
 IF (r->>'state' IS DISTINCT FROM state OR r->'evidence' IS DISTINCT FROM e) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CANONICAL_REPORT_INVALID' USING ERRCODE='42501';END IF;RETURN true;END$$;
CREATE FUNCTION design_canonical_verification.publish_report(token text,scope jsonb,tid text,r jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE a jsonb;t jsonb;old design_canonical_verification.reports;BEGIN
 IF session_user IS DISTINCT FROM 'design_canonical_verifier' THEN RAISE EXCEPTION 'CANONICAL_DENIED' USING ERRCODE='42501';END IF;a:=design_canonical_verification.resolve(token,scope);t:=design_canonical_verification.context(a,tid);PERFORM design_canonical_verification.check_report(t,r);SELECT * INTO old FROM design_canonical_verification.reports x WHERE x.task_id=tid;
 IF FOUND THEN IF (NOT old.active OR old.report IS DISTINCT FROM r) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CANONICAL_CONFLICT';END IF;ELSE INSERT INTO design_canonical_verification.reports VALUES(tid,r,true);END IF;
 t:=design_canonical_verification.context(design_canonical_verification.resolve(token,scope),tid);PERFORM design_canonical_verification.check_report(t,r);RETURN jsonb_build_object('task',t,'report',r);END$$;
CREATE FUNCTION design_canonical_verification.read_status(token text,scope jsonb,tid text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE t jsonb;r design_canonical_verification.reports;BEGIN
 IF session_user IS DISTINCT FROM 'design_normalization_runtime' THEN RAISE EXCEPTION 'CANONICAL_DENIED' USING ERRCODE='42501';END IF;t:=design_canonical_verification.context(design_canonical_verification.resolve(token,scope),tid);SELECT * INTO STRICT r FROM design_canonical_verification.reports x WHERE x.task_id=tid FOR SHARE;IF NOT r.active THEN RAISE EXCEPTION 'CANONICAL_DENIED';END IF;PERFORM design_canonical_verification.check_report(t,r.report);IF (t IS DISTINCT FROM design_canonical_verification.context(design_canonical_verification.resolve(token,scope),tid)) IS DISTINCT FROM false THEN RAISE EXCEPTION 'CANONICAL_CHANGED';END IF;RETURN jsonb_build_object('task',t,'report',r.report);END$$;
CREATE FUNCTION design_canonical_verification.read_verified(token text,scope jsonb,tid text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE r jsonb;BEGIN r:=design_canonical_verification.read_status(token,scope,tid);IF (r->'report'->>'state' IS DISTINCT FROM 'evidence_complete') IS DISTINCT FROM false THEN RAISE EXCEPTION 'CANONICAL_NOT_VERIFIED';END IF;RETURN r;END$$;
CREATE FUNCTION design_canonical_verification.revoke(kind text,tid text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$DECLARE n int;BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('design-prepared:transaction:v1',0));IF kind='task' AND session_user='design_canonical_authorizer' THEN UPDATE design_canonical_verification.tasks SET active=false WHERE id=tid AND active;
 ELSIF kind='report' AND session_user='design_canonical_verifier' THEN UPDATE design_canonical_verification.reports SET active=false WHERE task_id=tid AND active;ELSE RAISE EXCEPTION 'CANONICAL_DENIED' USING ERRCODE='42501';END IF;GET DIAGNOSTICS n=ROW_COUNT;RETURN n=1;END$$;
DO $$DECLARE f record;BEGIN FOR f IN SELECT p.oid::regprocedure sig FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='design_canonical_verification' LOOP EXECUTE format('ALTER FUNCTION %s OWNER TO design_managed_image_capability',f.sig);EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated,design_normalization_runtime,design_canonical_authorizer,design_canonical_verifier',f.sig);END LOOP;END$$;
GRANT EXECUTE ON FUNCTION design_canonical_verification.issue_task(text,jsonb,text,text,bigint) TO design_canonical_authorizer;
GRANT EXECUTE ON FUNCTION design_canonical_verification.read_task(text,jsonb,text),design_canonical_verification.guard_task(text,jsonb,text,text),design_canonical_verification.publish_report(text,jsonb,text,jsonb) TO design_canonical_verifier;
GRANT EXECUTE ON FUNCTION design_canonical_verification.read_status(text,jsonb,text),design_canonical_verification.read_verified(text,jsonb,text) TO design_normalization_runtime;
GRANT EXECUTE ON FUNCTION design_canonical_verification.revoke(text,text) TO design_canonical_authorizer,design_canonical_verifier;
REVOKE CREATE ON SCHEMA design_canonical_verification FROM design_managed_image_capability;
REVOKE ALL ON ALL TABLES IN SCHEMA design_canonical_verification FROM PUBLIC,anon,authenticated,design_normalization_runtime,design_canonical_authorizer,design_canonical_verifier;
